verification_commands.ac2:
set -u
# ac2 - the record is a DISCIPLINE artifact: JSON, in-repo, machine-checkable.
# It must name the four disclosed classes, and for each one the symptom, the
# surface, the OWNER and the disposition. The sweep-runner class must be
# recorded as orchestrator scratch tooling with the exclusion set it lacked -
# the record is the deliverable; a patch to that runner is NOT and cannot be.
RECORD=docs/state/outputs/t102_definer_pollution_policy.json
test -f "$RECORD" || { echo "ac2 RED: $RECORD missing - the discipline record is this card's second deliverable, not an optional note"; exit 1; }
command -v python3 >/dev/null 2>&1 || { echo "ac2 RED: python3 missing"; exit 1; }
python3 - "$RECORD" <<'PYAC2' || exit 1
import json, re, sys
path = sys.argv[1]
raw = open(path, "rb").read().replace(b"\r\n", b"\n")
try:
    doc = json.loads(raw.decode("utf-8"))
except Exception as exc:
    sys.stderr.write("ac2 RED: %s is not valid JSON (%s) - the record is machine-checkable or it is a note\n" % (path, exc)); raise SystemExit(1)
def fail(m):
    sys.stderr.write("ac2 RED: " + m + "\n"); raise SystemExit(1)
classes = doc.get("classes")
if not isinstance(classes, list) or not classes:
    fail("the record carries no 'classes' array - the four pollution classes are the deliverable")
print("ac2 evidence: record %s carries %d classes: %s" % (path, len(classes), [c.get("id") for c in classes]))
REQUIRED = {
    "copy-junction-dirt": ("build", "scratch"),
    "env-present": (".env", "env_quarantine"),
    "sweep-runner-allowlist": ("node_modules", "build", "scratch", ".git"),
    "wsl-node-stored-gates": ("134", "155"),
}
seen = {}
for c in classes:
    for k in ("id", "symptom", "surface", "owner", "disposition"):
        if not str(c.get(k, "")).strip():
            fail("class %r is missing the '%s' field - a class without an owner is an unowned obligation" % (c.get("id"), k))
    seen[str(c["id"])] = c
missing = [k for k in REQUIRED if k not in seen]
if missing:
    fail("the record is missing the classes %s - the four disclosed classes are named in the card and must all be present" % missing)
for cid, tokens in REQUIRED.items():
    blob = json.dumps(seen[cid]).lower()
    absent = [t for t in tokens if t.lower() not in blob]
    if absent:
        fail("class %s does not name %s - the class is recorded but not actionable" % (cid, absent))
    print("ac2 evidence: class %s names %s; owner=%s; disposition=%s" % (cid, tokens, seen[cid]["owner"], seen[cid]["disposition"]))
# The sweep-runner boundary must be stated as OUT of this repository's reach.
sr = json.dumps(seen["sweep-runner-allowlist"]).lower()
if not re.search(r"orchestrator|scratch tooling|not a repo artifact|out of scope", sr):
    fail("the sweep-runner class does not name its owner as orchestrator scratch tooling - B2 is recorded as a discipline obligation precisely because this card cannot and must not patch that runner")
if re.search(r"(fix|patch|update|edit)[a-z]* (the )?(sweep|runner)[a-z ]*(in|inside) (this )?(repo|repository)", sr):
    fail("the sweep-runner class claims the RUNNER ITSELF is patched in this repository - that is out of scope and the card must not claim it")
# The two neighbour legs must be recorded at the groom-measured state, not the
# survey claim (214 is GREEN under build/scratch dirt after t101; 217 is RED on
# its own determinism premise with no .env present).
neigh = json.dumps(doc).lower()
for leg, state in (("214", "green"), ("217", "red")):
    if leg not in neigh:
        fail("the record does not mention tests[%s] - the neighbour class is part of the boundary this card records" % leg)
if not ("214" in neigh and "green" in neigh):
    fail("the record does not state tests[214] as GREEN at this base - groom measured it GREEN on a tree carrying build/+scratch/ dirt (t101 made leg 214's plant skip()-exempt); carrying survey's stale RED claim would send a builder to fix a leg that is not broken")
print("ac2 evidence: neighbour legs recorded at groom-measured state - tests[214] GREEN under build/+scratch/ dirt (t101), tests[217] RED on its own determinism premise with no .env present")
# The record must not smuggle a product change: it is a JSON artifact only.
if re.search(r'"(files_to_(write|change|patch))"\s*:\s*\[[^\]]*"(backend|frontend|tests|scripts)/', json.dumps(doc)):
    fail("the record claims product files to write - the record is a discipline artifact, this card's only product change is the SKIP_DIRS line in ac1")
print("ac2 GREEN: DISCIPLINE RECORD SHIPPED - %d classes each with symptom/surface/owner/disposition, the sweep-runner allowlist obligation named as ORCHESTRATOR SCRATCH TOOLING with the exclusion set it lacked (node_modules, build, scratch, .git) and explicitly NOT patched from this repository, and the two neighbour legs recorded at their groom-measured state" % len(classes))
PYAC2
